import XCTest
@testable import MatchPost

final class EXIFReaderTests: XCTestCase {
    func testExtractFromDataWithNoEXIF() {
        // Plain 1x1 white JPEG has no EXIF
        let data = Data(base64Encoded: "")!
        let exif = EXIFReader.extract(from: data)
        XCTAssertNil(exif.date)
        XCTAssertNil(exif.coordinate)
    }

    func testExtractReturnsNilCoordinateForZeroGPS() {
        let data = Data(base64Encoded: "")!
        let exif = EXIFReader.extract(from: data)
        // coordinate with 0,0 should still return nil (invalid GPS)
        if let coord = exif.coordinate {
            XCTAssertNotEqual(coord.latitude, 0)
        }
    }
}
